+pub fn select<'a>(cases: &'a [Case], split: &str, only: &str) -> Vec<&'a Case> {
+    cases
+        .iter()
+        .filter(|c| (split == "all" || c.split == split) && c.id.starts_with(only))
+        .collect()
+}
